import {Game,rooms,boxes,groundAt} from './simulation.js';
import {createWorld,THREE} from './world.js';
const $=id=>document.getElementById(id);const ui={menu:$('menu'),hud:$('hud'),dialog:$('dialog-backdrop')};
let world;try{world=createWorld($('game'));}catch(e){$('loading').innerHTML='<p>当前浏览器未能启动 3D 场景</p><p>请启用硬件加速，或使用支持 WebGL 的浏览器重试。</p>';throw e;}
const storage={get(k){try{return localStorage.getItem(k)}catch{return null}},set(k,v){try{localStorage.setItem(k,v)}catch{}}};
let mode='adventure',skin=storage.get('marble.skin')||'mint',sound=false,audio=null,overview=false,yaw=0,zoom=27,lastTime=0,accumulator=0,t=0,toastTimer=0,prevState='',lastFocus=null;
const keys=new Set();const input={x:0,z:0,jump:false,dash:false};const touch={x:0,z:0};
function initAudio(){if(!audio){try{audio=new(window.AudioContext||window.webkitAudioContext)()}catch{}}if(audio?.state==='suspended')audio.resume();}
function beep(freq=440,duration=.13,type='sine',volume=.08,delay=0){if(!sound||!audio)return;const osc=audio.createOscillator(),gain=audio.createGain();osc.connect(gain);gain.connect(audio.destination);osc.frequency.value=freq;osc.type=type;const start=audio.currentTime+delay;gain.gain.setValueAtTime(0,start);gain.gain.linearRampToValueAtTime(volume,start+.01);gain.gain.exponentialRampToValueAtTime(.001,start+duration);osc.start(start);osc.stop(start+duration);}
function chord(){[523.25,659.25,783.99,1046.5].forEach((f,i)=>beep(f,.3,'sine',.06,i*.08));}
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3200);}
const game=new Game((type,data)=>{if(type==='star'){world.burst(data.x,data.y,data.z);beep(700+game.collected%7*100,.15,'sine',.065);}if(type==='badge'){world.burst(game.pos.x,game.pos.y+1,game.pos.z,0x73efb7,30);chord();toast(['积木徽章到手！沿金色星星前往音乐厨房','旋律徽章到手！通往云朵卧室的门已打开','美梦徽章到手！前往金色星门完成冒险'][data]);}if(type==='checkpoint'){chord();toast('检查点已保存 · '+rooms[data].name);game.lives=Math.min(5,game.lives+1);}if(type==='jump')beep(380,.12,'sine',.04);if(type==='dash'){beep(220,.2,'triangle',.08);world.burst(game.pos.x,game.pos.y,game.pos.z,0xaefff0,9);}if(type==='spring'){beep(660,.22,'triangle');toast('弹簧垫！在空中也能控制方向');}if(type==='bumper')beep(280,.18,'triangle',.08);if(type==='hit'){beep(110,.18,'sawtooth',.035);toast('撞到机关了 · 跳跃可以越过旋转棒');}if(type==='respawn')beep(260,.22,'sine');if(type==='note')beep([523.25,659.25,783.99][data],.4,'triangle',.06);if(type==='toast')toast(data);if(type==='win'){chord();showWin();}});
function applySkin(s){if(!['mint','pink','gold','blue'].includes(s))s='mint';skin=s;world.setSkin(s);storage.set('marble.skin',s);document.querySelectorAll('.swatch').forEach(el=>el.classList.toggle('active',el.dataset.skin===s));$('skin-name').textContent={mint:'薄荷泡泡',pink:'草莓糖',gold:'蜂蜜星球',blue:'银河玻璃珠'}[s];}applySkin(skin);
function timeFormat(seconds){const m=Math.floor(seconds/60),s=Math.floor(seconds%60);return `${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}.${Math.floor(seconds%1*10)}`;}
function bestText(){const saved=Number(storage.get('marble.best.'+mode));$('best').textContent=saved>0?'本机最佳记录  '+timeFormat(saved):'';}bestText();
function start(){lastTime=performance.now();accumulator=0;initAudio();game.start(mode);ui.menu.classList.add('hidden');ui.hud.classList.remove('hidden');$('scene-caption').classList.add('hidden');document.body.classList.add('playing');ui.dialog.classList.add('hidden');$('touch').classList.toggle('hidden',!matchMedia('(pointer:coarse)').matches);keys.clear();input.jump=false;input.dash=false;yaw=0;overview=false;prevState='';toast(mode==='time'?'计时开始！先踩下客厅里的薄荷色按钮':'WASD 滚动 · 先找到客厅里的薄荷色按钮');}
$('start').addEventListener('click',start);document.querySelectorAll('.mode').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;document.querySelectorAll('.mode').forEach(el=>el.classList.toggle('active',el===b));$('start').innerHTML=(mode==='time'?'开始计时挑战':'开始冒险')+' <span>▷</span>';bestText();});document.querySelectorAll('.swatch').forEach(b=>b.onclick=()=>applySkin(b.dataset.skin));
function toggleSound(){sound=!sound;if(sound)initAudio();$('sound').setAttribute('aria-label',sound?'关闭音效':'开启音效');$('sound').innerHTML='♫'+(sound?'':'<span class="off-mark"></span>');if(sound)beep(660,.15);return sound;}$('sound').onclick=toggleSound;
function showDialog(type){if(game.status==='won'&&type==='pause')return;lastFocus=document.activeElement;if(game.status==='playing')game.status='paused';keys.clear();touch.x=touch.z=0;$('stick').style.transform='translate(0,0)';ui.dialog.classList.remove('hidden');$('touch').classList.add('hidden');$('resume').textContent=game.status==='menu'?'知道了':'继续冒险';$('restart').classList.toggle('hidden',game.status==='menu');$('back-menu').classList.toggle('hidden',game.status==='menu');$('dialog-icon').textContent=type==='help'?'⌘':'Ⅱ';$('dialog-title').textContent=type==='help'?'让冒险滚起来':'休息一下';$('dialog-content').innerHTML=type==='help'?'<div class="help-row"><span>滚动 / 控制空中方向</span><kbd>WASD / 方向键</kbd></div><div class="help-row"><span>跳跃</span><kbd>SPACE</kbd></div><div class="help-row"><span>冲刺（3 秒充能）</span><kbd>SHIFT</kbd></div><div class="help-row"><span>返回检查点</span><kbd>R</kbd></div><div class="help-row"><span>俯瞰全屋 / 暂停</span><kbd>F / ESC</kbd></div><p>拖动画面调整视角，滚轮调整远近。<br>收集三个房间徽章，进入金色星门。<br>星星是可选奖励，找找书本坡道的尽头！<br>手机使用左侧摇杆和右侧跳跃、冲刺按钮。<br>计时挑战每次跌落额外增加 5 秒。</p>':'<p>你的弹珠在这里等你。<br>闭上眼睛，下一站会是什么？</p>';$('resume').focus();}
function closeDialog(){if(game.status==='won'){toMenu();return;}ui.dialog.classList.add('hidden');if(game.status==='paused'){lastTime=performance.now();accumulator=0;game.status='playing';$('touch').classList.toggle('hidden',!matchMedia('(pointer:coarse)').matches);}keys.clear();lastFocus?.focus();}
function toMenu(){ui.dialog.classList.add('hidden');ui.menu.classList.remove('hidden');ui.hud.classList.add('hidden');$('touch').classList.add('hidden');$('scene-caption').classList.remove('hidden');document.body.classList.remove('playing');game.reset(mode);keys.clear();overview=false;bestText();$('start').focus();}
function showWin(){const best=Number(storage.get('marble.best.'+mode));const isBest=!best||game.elapsed<best;if(isBest)storage.set('marble.best.'+mode,String(game.elapsed));$('touch').classList.add('hidden');ui.dialog.classList.remove('hidden');$('dialog-icon').textContent='✦';$('dialog-title').textContent='小弹珠，大冒险家';const rank=game.collected>=30?'星星收藏家':game.collected>=18?'玩具屋探险家':'勇敢的小弹珠';$('dialog-content').innerHTML=`<p>三个房间，三枚徽章，一段属于你的旅程。<br>${rank}${isBest?' · 刷新本机最佳记录！':''}</p><div class="results"><div><b>${timeFormat(game.elapsed)}</b><small>完成用时</small></div><div><b>${game.collected}<span style="font-size:14px"> / 36</span></b><small>收集星星</small></div></div><p>还想探索？换一颗弹珠，找齐隐藏的星星。</p>`;$('resume').textContent='再冒险一次';$('restart').classList.add('hidden');$('back-menu').classList.remove('hidden');$('resume').focus();for(let i=0;i<5;i++)setTimeout(()=>world.burst(35,6,-5,[0xffd055,0x6aefc5,0xf88fb5][i%3],30),i*280);}
$('resume').onclick=()=>game.status==='won'?start():closeDialog();$('restart').onclick=start;$('back-menu').onclick=toMenu;$('dialog-close').onclick=closeDialog;$('help').onclick=()=>showDialog('help');$('pause').onclick=()=>{if(game.status==='playing')showDialog('pause');else if(game.status==='paused')closeDialog();};document.querySelector('.brand').onclick=e=>{e.preventDefault();if(game.status==='playing')showDialog('pause');else if(game.status!=='menu')toMenu();};
const handled=['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space','ShiftLeft','ShiftRight','Escape','KeyR','KeyF'];window.addEventListener('keydown',e=>{if(handled.includes(e.code)&&game.status==='playing')e.preventDefault();if(e.code==='Escape'){e.preventDefault();if(!ui.dialog.classList.contains('hidden'))closeDialog();else if(game.status==='playing')showDialog('pause');return;}if(e.code==='Tab'&&!ui.dialog.classList.contains('hidden')){const elements=[...ui.dialog.querySelectorAll('button:not(.hidden)')];const first=elements[0],last=elements.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}return;}if(game.status!=='playing')return;keys.add(e.code);if(!e.repeat&&e.code==='Space')input.jump=true;if(!e.repeat&&(e.code==='ShiftLeft'||e.code==='ShiftRight'))input.dash=true;if(!e.repeat&&e.code==='KeyR')game.respawn();if(!e.repeat&&e.code==='KeyF')overview=!overview;});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{keys.clear();touch.x=touch.z=0;if(game.status==='playing')showDialog('pause');});document.addEventListener('visibilitychange',()=>{if(document.hidden&&game.status==='playing')showDialog('pause');});
let dragging=false,dragX=0;world.renderer.domElement.style.touchAction='none';world.renderer.domElement.addEventListener('pointerdown',e=>{if(game.status!=='playing')return;dragging=true;dragX=e.clientX;world.renderer.domElement.setPointerCapture(e.pointerId);});world.renderer.domElement.addEventListener('pointermove',e=>{if(dragging){yaw-=(e.clientX-dragX)*.006;dragX=e.clientX;}});world.renderer.domElement.addEventListener('pointerup',()=>dragging=false);world.renderer.domElement.addEventListener('pointercancel',()=>dragging=false);world.renderer.domElement.addEventListener('wheel',e=>{if(game.status==='playing'){e.preventDefault();zoom=Math.max(15,Math.min(42,zoom+e.deltaY*.025));}},{passive:false});
let joyId=null;const joy=$('joystick');function moveJoy(e){if(e.pointerId!==joyId)return;const r=joy.getBoundingClientRect();let x=e.clientX-r.left-r.width/2,z=e.clientY-r.top-r.height/2;const len=Math.hypot(x,z),max=42;if(len>max){x*=max/len;z*=max/len;}touch.x=x/max;touch.z=z/max;$('stick').style.transform=`translate(${x}px,${z}px)`;}joy.addEventListener('pointerdown',e=>{joyId=e.pointerId;joy.setPointerCapture(joyId);moveJoy(e);});joy.addEventListener('pointermove',moveJoy);function resetJoy(){joyId=null;touch.x=touch.z=0;$('stick').style.transform='translate(0,0)';}joy.addEventListener('pointerup',resetJoy);joy.addEventListener('pointercancel',resetJoy);$('touch-jump').addEventListener('pointerdown',e=>{e.preventDefault();input.jump=true;});$('touch-dash').addEventListener('pointerdown',e=>{e.preventDefault();input.dash=true;});
const mini=$('minimap').getContext('2d');function map(){mini.clearRect(0,0,240,146);const sx=x=>14+(x+40)*2.65,sz=z=>12+(z+23)*2.4;mini.fillStyle='#d7e8cd';mini.fillRect(14,12,69,110);mini.fillStyle='#f4dfad';mini.fillRect(83,12,69,110);mini.fillStyle='#dfd0e8';mini.fillRect(152,12,74,110);for(const b of boxes){mini.fillStyle='#a49b886b';mini.fillRect(sx(b.x-b.w/2),sz(b.z-b.d/2),b.w*2.65,b.d*2.4);}for(let i=0;i<2;i++)if(!game.badges[i]){mini.fillStyle='#597569';mini.fillRect(sx(i===0?-13:13)-1,sz(4),3,8*2.4);}for(const s of game.stars)if(!s.taken){mini.fillStyle='#d9a529';mini.beginPath();mini.arc(sx(s.x),sz(s.z),1.7,0,Math.PI*2);mini.fill();}let target=!game.badges[0]?[-24,-9]:!game.badges[1]?[[-7,-9],[0,-9],[7,-9]][game.piano]:!game.badges[2]?[21,-1]:[35,-5];mini.strokeStyle='#fffdf4';mini.fillStyle='#248d79';mini.lineWidth=1.5;mini.beginPath();mini.arc(sx(target[0]),sz(target[1]),4+Math.sin(t*3),0,Math.PI*2);mini.fill();mini.stroke();mini.fillStyle='#204d60';mini.beginPath();mini.arc(sx(game.pos.x),sz(game.pos.z),3.5,0,Math.PI*2);mini.fill();mini.stroke();mini.fillStyle='#617e73';mini.font='9px sans-serif';mini.textAlign='center';mini.fillText('玩具屋地图 · 绿色为当前目标',120,137);}
function updateUI(){const state=[game.collected,game.room,game.lives,game.piano,...game.badges].join('|');if(state!==prevState){prevState=state;$('stars').textContent=game.collected;$('room').textContent=rooms[game.room].name;$('room-no').textContent='0'+(game.room+1);$('objective').textContent=game.badges.every(Boolean)?'三个徽章集齐了！滚进金色星门':!game.badges[0]?rooms[0].goal:!game.badges[1]?(game.room===0?'积木门已打开 · 前往音乐厨房':rooms[1].goal):!game.badges[2]?(game.room<2?'旋律门已打开 · 前往云朵卧室':rooms[2].goal):'';$('hearts').textContent='♥ '.repeat(game.lives)+'♡ '.repeat(5-game.lives);$('hearts').setAttribute('aria-label',game.lives+' 颗心');for(let i=0;i<3;i++){$('badge-'+i).classList.toggle('earned',game.badges[i]);$('map-'+i).classList.toggle('active',game.room===i);}}$('timer').textContent=timeFormat(game.elapsed);$('dash-meter').style.width=(1-game.dashCd/3)*100+'%';$('dash-label').textContent=game.dashCd>0?`充能 ${game.dashCd.toFixed(1)} 秒`:'冲刺就绪';map();}
const camTarget=new THREE.Vector3(),desired=new THREE.Vector3(),look=new THREE.Vector3();world.camera.position.set(64,69,87);camTarget.set(-9,0,0);function animate(now){requestAnimationFrame(animate);const realDt=(now-lastTime)/1000||.016;const dt=Math.min(realDt,.05);if(game.status==='playing'&&realDt>dt)game.elapsed+=realDt-dt;lastTime=now;t+=dt;let x=(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0)+touch.x;let z=(keys.has('KeyS')||keys.has('ArrowDown')?1:0)-(keys.has('KeyW')||keys.has('ArrowUp')?1:0)+touch.z;const len=Math.hypot(x,z);if(len>1){x/=len;z/=len;}input.x=x*Math.cos(yaw)+z*Math.sin(yaw);input.z=-x*Math.sin(yaw)+z*Math.cos(yaw);accumulator+=dt;while(accumulator>=1/120){game.update(1/120,input);input.jump=false;input.dash=false;accumulator-=1/120;}world.update(game,dt,t);if(game.status==='menu'){const narrow=innerWidth<700;desired.set(narrow?58:65,68,narrow?92:86);look.set(narrow?-11:-13,0,0);desired.x+=Math.sin(t*.1)*2;look.z=-1;}else if(overview){desired.set(34,84,65);look.set(0,0,0);}else{const p=game.pos;desired.set(p.x+Math.sin(yaw)*zoom,p.y+zoom*.83+4,p.z+Math.cos(yaw)*zoom);look.set(p.x,p.y+.2,p.z-1);}const lerp=1-Math.exp(-dt*3.5);world.camera.position.lerp(desired,lerp);camTarget.lerp(look,lerp);world.camera.lookAt(camTarget);world.renderer.render(world.scene,world.camera);if(game.status!=='menu')updateUI();}
window.addEventListener('resize',world.resize);window.marbleReady=true;$('loading').classList.add('hidden');requestAnimationFrame(animate);
// Readable state for accessibility tools and browser-based game agents.
const state=()=>({status:game.status,mode:game.mode,room:rooms[game.room].name,stars:game.collected,totalStars:36,badges:[...game.badges],lives:game.lives,elapsed:Number(game.elapsed.toFixed(2)),position:{...game.pos},objective:$('objective').textContent});
window.marbleGame={state,start,returnToCheckpoint:()=>{if(game.status==='playing')game.respawn();return state();},pause:()=>{if(game.status==='playing')showDialog('pause');return state();}};
if(document.modelContext?.registerTool){const lifecycle=new AbortController();for(const tool of [{name:'read_marble_adventure',title:'查看弹珠冒险状态',description:'Read the current room, score, badges, time and objective.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>state()},{name:'start_marble_adventure',title:'开始弹珠冒险',description:'Start a new game, resetting the current run. Choose adventure or time challenge.',inputSchema:{type:'object',properties:{mode:{type:'string',enum:['adventure','time']}},required:['mode'],additionalProperties:false},annotations:{readOnlyHint:false},execute:args=>{if(!args||!['adventure','time'].includes(args.mode))throw new Error('mode must be adventure or time');mode=args.mode;start();return state();}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
